/**
 * Test cases for the data-flow page: the nine `./emu` runs that passed on the AWS FPGA
 * (stage4_fpga/evidence/fpga_emu_R*.png, copied verbatim) plus a few extra cases whose expected
 * values are generated by running the verified controller model.
 */
import { RackSentinelController } from "./controller";
import { CMD, encodeCommand, frameValue, hex, replyValue } from "./protocol";

export interface FlowCase {
  id: string;
  title: string;
  /** Ali's moment, one line. */
  moment: string;
  /** What the case proves. */
  story: string;
  line: string;
  /** Screenshot of the run on the AWS FPGA, when it has one. */
  fpga?: string;
  /** Pixel size of that screenshot. */
  fpgaSize?: [number, number];
  /** The twin scenario that tells the same story. */
  scenario?: string;
}

