type Action = { send: [cmd: number, data: number]; corrupt?: number } | { input: number } | { out: true };

/** Build an `./emu` line by running the controller, like the demo page's generator. */
export function buildLine(actions: Action[]): string {
  const c = new RackSentinelController();
  const parts = ["-d 0xF0"];
  for (const a of actions) {
    if ("send" in a) {
      const f = encodeCommand(a.send[0], a.send[1], a.corrupt ?? 0);
      const r = c.receiveFrame(f);
      parts.push(`-t4 0x${hex(frameValue(f), 8)}`, `-r${r.reply.length} 0x${hex(replyValue(r.reply), r.reply.length * 2)}`);
    } else if ("input" in a) {
      c.setInputs({ reset: !!(a.input & 1), leak: !!(a.input & 2) });
      parts.push(`-i 0x${hex(a.input)}`);
    } else {
      parts.push(`-o 0x${hex(c.pins & 0xf0)}`);
    }
  }
  return `./emu ${parts.join(" ")}`;
}

const EXTRA_CASES: FlowCase[] = [
  {
    id: "X1",
    title: "Damaged packet",
    moment: "Interference flips a bit on the wire.",
    story: "A safe 26.0 °C reading arrives with one DATA bit flipped. The CRC no longer matches: reply 5A, nothing changes, and COUNTERS counts the reject.",
    line: buildLine([{ send: [CMD.TEMP, 70] }, { out: true }, { send: [CMD.TEMP, 52], corrupt: 0x01 }, { out: true }, { send: [CMD.COUNTERS, 0] }]),
    scenario: "corrupt",
  },
  {
    id: "X2",
    title: "Bad values",
    moment: "A broken sensor and a typo in a setting.",
    story: "A temperature of raw 0 means no reading, and a Warm threshold above Hot would break the order. Both are answered 3C and change nothing.",
    line: buildLine([{ send: [CMD.TEMP, 44] }, { send: [CMD.TEMP, 0] }, { send: [CMD.SET_WARM, 66] }, { send: [CMD.STATUS, 0] }]),
    scenario: "invalid",
  },
  {
    id: "X3",
    title: "Changing a threshold",
    moment: "The site wants the fans to boost earlier.",
    story: "26.0 °C is Normal. SET_WARM 25.0 °C is accepted and stored with ECC, and the same 26.0 °C reading is now Warm.",
    line: buildLine([{ send: [CMD.TEMP, 52] }, { out: true }, { send: [CMD.SET_WARM, 50] }, { send: [CMD.TEMP, 52] }, { out: true }]),
  },
];

export const FLOW_CASES: FlowCase[] = [...FPGA_CASES, ...EXTRA_CASES];
export const flowCase = (id: string) => FLOW_CASES.find((c) => c.id === id);
